const FormField = ({ label, id, type = "text", required = false, helperText, value, onChange, error, placeholder }) => {
  const describedBy = [];
  if (helperText) describedBy.push(`${id}-helper`);
  if (error) describedBy.push(`${id}-error`);

  return (
