        {error}
      </div>
    </div>
  );
};

const ContactForm = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: ''
  });

  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const successHeadingRef = React.useRef(null);
  const mainHeadingRef = React.useRef(null);

  React.useEffect(() => {
    if (submitted && successHeadingRef.current) {
      successHeadingRef.current.focus();
    }
  }, [submitted]);

  const validate = () => {
    const newErrors = {};

    if (!formData.fullName.trim()) {
      newErrors.fullName = "Full name is required.";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email address is required.";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = "Please enter a valid email address.";
    }

    if (formData.phone && !/^\(\d{3}\)\s\d{3}-\d{4}$/.test(formData.phone)) {
        newErrors.phone = "Format should be (123) 456-7890";
    }

    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const validationErrors = validate();
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setSubmitted(true);
      console.log('Form submitted:', formData);
    } else {
      // Focus first invalid field
      const firstError = Object.keys(validationErrors)[0];
      const element = document.getElementById(firstError);
      if (element) {
        element.focus();
      }
    }
  };

  if (submitted) {
    return (
      <main id="main-content" tabIndex="-1">
        <h1 ref={successHeadingRef} tabIndex="-1">Thank you!</h1>
        <p>Your message has been received. We will get back to you shortly.</p>
        <button 
          type="button" 
          onClick={() => { 
            setSubmitted(false); 
            setFormData({fullName: '', email: '', phone: ''}); 
            setErrors({});
          }}
          style={{ marginTop: '1.5rem' }}
        >
          Send another message
        </button>
      </main>
    );
  }

  return (
    <main id="main-content" tabIndex="-1">
      <h1 ref={mainHeadingRef}>Contact Support</h1>
      <form onSubmit={handleSubmit} noValidate>
        <FormField
          label="Full Name"
          id="fullName"
          required={true}
          value={formData.fullName}
          onChange={(val) => setFormData({ ...formData, fullName: val })}
          error={errors.fullName}
          placeholder="John Doe"
        />
        <FormField
          label="Email Address"
          id="email"
          type="email"
          required={true}
          value={formData.email}
          onChange={(val) => setFormData({ ...formData, email: val })}
          error={errors.email}
          placeholder="john@example.com"
        />
        <FormField
          label="Phone Number"
          id="phone"
          type="tel"
          required={false}
          helperText="Format: (123) 456-7890"
          value={formData.phone}
          onChange={(val) => setFormData({ ...formData, phone: val })}
          error={errors.phone}
          placeholder="(123) 456-7890"
        />
        <button type="submit">Submit</button>
      </form>
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);
