', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_basic/simple-contact-form--framework-react--style-dark--validation-message-present/google/gemini-3-flash-preview__s1/app.js', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents='const { useState, useRef, useEffect } = React;

const FormField = ({ label, id, type = "text", required = false, helperText, value, onChange, error, placeholder }) => {
  const describedBy = [];
  if (helperText) describedBy.push(`${id}-helper`);
  if (error) describedBy.push(`${id}-error`);

  return (
    <div className="form-field">
      <label htmlFor={id}>
        {label}
        {required && <span aria-hidden="true" style={{ color: 'var(--error-color)', marginLeft: '4px' }}>*</span>}
      </label>
      <input
        type={type}
        id={id}
        name={id}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        required={required}
        aria-required={required}
        aria-invalid={!!error}
        aria-describedby={describedBy.join(' ') || undefined}
        placeholder={placeholder}
      />
      {helperText && (
        <div id={`${id}-helper`} className="helper-text">
          {helperText}
        </div>
      )}
      <div id={`${id}-error`} className="error-message" role="alert">
        {error}
      </div>
    </div>
  );
};

const ContactForm = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: ''
  });

  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const successHeadingRef = React.useRef(null);
  const mainHeadingRef = React.useRef(null);

  React.useEffect(() => {
    if (submitted && successHeadingRef.current) {
      successHeadingRef.current.focus();
    }
  }, [submitted]);

  const validate = () => {
    const newErrors = {};

    if (!formData.fullName.trim()) {
      newErrors.fullName = "Full name is required.";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email address is required.";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = "Please enter a valid email address.";
    }

    if (formData.phone && !/^\(\d{3}\)\s\d{3}-\d{4}$/.test(formData.phone)) {
        newErrors.phone = "Format should be (123) 456-7890";
    }

    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const validationErrors = validate();
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      setSubmitted(true);
      console.log('Form submitted:', formData);
    } else {
      // Focus first invalid field
      const firstError = Object.keys(validationErrors)[0];
      const element = document.getElementById(firstError);
      if (element) {
        element.focus();
      }
    }
  };

  if (submitted) {
    return (
      <main id="main-content" tabIndex="-1">
        <h1 ref={successHeadingRef} tabIndex="-1">Thank you!</h1>
        <p>Your message has been received. We will get back to you shortly.</p>
        <button 
          type="button" 
          onClick={() => { 
            setSubmitted(false); 
            setFormData({fullName: '', email: '', phone: ''}); 
            setErrors({});
          }}
          style={{ marginTop: '1.5rem' }}
        >
          Send another message
        </button>
      </main>
    );
  }

  return (
    <main id="main-content" tabIndex="-1">
      <h1 ref={mainHeadingRef}>Contact Support</h1>
      <form onSubmit={handleSubmit} noValidate>
        <FormField
          label="Full Name"
          id="fullName"
          required={true}
          value={formData.fullName}
          onChange={(val) => setFormData({ ...formData, fullName: val })}
          error={errors.fullName}
          placeholder="John Doe"
        />
        <FormField
          label="Email Address"
          id="email"
          type="email"
          required={true}
          value={formData.email}
          onChange={(val) => setFormData({ ...formData, email: val })}
          error={errors.email}
          placeholder="john@example.com"
        />
        <FormField
          label="Phone Number"
          id="phone"
          type="tel"
          required={false}
          helperText="Format: (123) 456-7890"
          value={formData.phone}
          onChange={(val) => setFormData({ ...formData, phone: val })}
          error={errors.phone}
          placeholder="(123) 456-7890"
        />
        <button type="submit">Submit</button>
      </form>
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);
